<?php
namespace App\Http\Controllers;
use App\Models\Booking;use App\Models\Vehicle;use Illuminate\Http\Request;use Carbon\Carbon;
class BookingController extends Controller {public function index(){$bookings=Booking::with('vehicle')->where('user_id',auth()->id())->latest()->paginate(10);return view('bookings.index',compact('bookings'));}public function store(Request $r,$id){$d=$r->validate(['start_date'=>'required|date|after_or_equal:today','end_date'=>'required|date|after_or_equal:start_date','notes'=>'nullable|max:500']);$v=Vehicle::where('status','available')->findOrFail($id);$conflict=Booking::where('vehicle_id',$id)->whereIn('status',['pending','approved'])->where('start_date','<=',$d['end_date'])->where('end_date','>=',$d['start_date'])->exists();if($conflict)return back()->with('error','Kendaraan sudah dipesan pada tanggal tersebut.');$days=Carbon::parse($d['start_date'])->diffInDays(Carbon::parse($d['end_date']))+1;Booking::create(['user_id'=>auth()->id(),'vehicle_id'=>$id,'start_date'=>$d['start_date'],'end_date'=>$d['end_date'],'total_days'=>$days,'total_price'=>$days*$v->price_per_day,'status'=>'pending','notes'=>isset($d['notes'])?$d['notes']:null]);return redirect()->route('bookings')->with('success','Booking dikirim.');}}